const db = require('better-sqlite3')('/workspace/world.db');

// For a one-stop JFK -> ??? -> LAX on 2026-09-09, we need:
// 1) A flight from JFK to some intermediate on 2026-09-09
// 2) A flight from that intermediate to LAX on 2026-09-09 (or possibly next day)

const allFlights = db.prepare('SELECT * FROM flights').all();
const targetDate = '2026-09-09';

// Flights from JFK on 2026-09-09
let fromJFK = [];
allFlights.forEach(f => {
  const dates = JSON.parse(f.dates_json || '{}');
  if (f.origin === 'JFK' && dates[targetDate]) {
    fromJFK.push({...f, dateInfo: dates[targetDate]});
  }
});

// Flights to LAX on 2026-09-09
let toLAX = [];
allFlights.forEach(f => {
  const dates = JSON.parse(f.dates_json || '{}');
  if (f.destination === 'LAX' && (dates[targetDate] || dates['2026-09-10'])) {
    toLAX.push({...f, dateInfo: dates[targetDate] || dates['2026-09-10'], date: dates[targetDate] ? targetDate : '2026-09-10'});
  }
});

console.log('Flights from JFK on ' + targetDate + ':', fromJFK.length);
fromJFK.forEach(f => console.log(' ', f.flight_id, '->', f.destination, JSON.stringify(f.dateInfo)));

console.log('\nFlights to LAX on ' + targetDate + ' or 2026-09-10:', toLAX.length);
toLAX.forEach(f => console.log(' ', f.flight_id, f.origin, '->', 'LAX', 'date:', f.date, JSON.stringify(f.dateInfo)));

// Check for connections
console.log('\n=== Possible connections ===');
fromJFK.forEach(leg1 => {
  toLAX.forEach(leg2 => {
    if (leg1.destination === leg2.origin) {
      console.log('Connection found:', leg1.flight_id, 'JFK->' + leg1.destination, '+', leg2.flight_id, leg2.origin + '->LAX');
    }
  });
});
"

